/**
 * Migration runner and schema definitions.
 */

const MIGRATIONS = [
  {
    version: 1,
    description: "Initial schema for batches, addresses, snapshots, and wizard sessions",
    up: (db) => {
      db.exec(`
        -- Batches generated by users
        CREATE TABLE IF NOT EXISTS generated_batches (
          id TEXT PRIMARY KEY,
          user_id INTEGER NOT NULL,
          created_at INTEGER NOT NULL,
          requested INTEGER NOT NULL,
          received INTEGER NOT NULL,
          selected_types_json TEXT NOT NULL,
          status TEXT NOT NULL,
          errors_json TEXT
        );

        CREATE INDEX IF NOT EXISTS idx_batches_user_created 
          ON generated_batches(user_id, created_at DESC);

        -- Individual generated email addresses
        CREATE TABLE IF NOT EXISTS generated_addresses (
          id TEXT PRIMARY KEY,
          batch_id TEXT NOT NULL REFERENCES generated_batches(id) ON DELETE CASCADE,
          user_id INTEGER NOT NULL,
          email TEXT NOT NULL,
          type_id INTEGER,
          created_at INTEGER NOT NULL,
          UNIQUE(batch_id, email)
        );

        CREATE INDEX IF NOT EXISTS idx_addresses_user_email 
          ON generated_addresses(user_id, email);

        -- Inbox snapshots
        CREATE TABLE IF NOT EXISTS inbox_snapshots (
          id TEXT PRIMARY KEY,
          user_id INTEGER NOT NULL,
          email TEXT NOT NULL,
          created_at INTEGER NOT NULL,
          expires_at INTEGER NOT NULL
        );

        CREATE INDEX IF NOT EXISTS idx_snapshots_user_email 
          ON inbox_snapshots(user_id, email);

        -- Messages mapped inside inbox snapshots
        CREATE TABLE IF NOT EXISTS inbox_snapshot_messages (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          snapshot_id TEXT NOT NULL REFERENCES inbox_snapshots(id) ON DELETE CASCADE,
          ordinal INTEGER NOT NULL,
          message_id TEXT NOT NULL,
          sender TEXT NOT NULL,
          subject TEXT NOT NULL,
          received_at TEXT,
          UNIQUE(snapshot_id, ordinal)
        );

        -- Wizard sessions for multi-select and flow state
        CREATE TABLE IF NOT EXISTS wizard_sessions (
          id TEXT PRIMARY KEY,
          user_id INTEGER NOT NULL,
          chat_id INTEGER NOT NULL,
          state TEXT NOT NULL,
          payload_json TEXT NOT NULL,
          expires_at INTEGER NOT NULL
        );

        CREATE INDEX IF NOT EXISTS idx_wizard_user 
          ON wizard_sessions(user_id);
      `);
    }
  }
];

/**
 * Runs pending database migrations.
 *
 * @param {import("better-sqlite3").Database} db
 */
export function runMigrations(db) {
  db.exec(`
    CREATE TABLE IF NOT EXISTS schema_migrations (
      version INTEGER PRIMARY KEY,
      applied_at INTEGER NOT NULL
    );
  `);

  const appliedRows = db.prepare("SELECT version FROM schema_migrations").all();
  const appliedVersions = new Set(appliedRows.map((r) => r.version));

  const applyTx = db.transaction((migration) => {
    migration.up(db);
    db.prepare("INSERT INTO schema_migrations (version, applied_at) VALUES (?, ?)").run(
      migration.version,
      Date.now()
    );
  });

  for (const migration of MIGRATIONS) {
    if (!appliedVersions.has(migration.version)) {
      applyTx(migration);
    }
  }
}

